export async function twitterUploadMediaAction(filePath, options) {
 const key = ();
 const = requireCookies();
 const spinner = ora("Uploading media...").start();
 let formData;
 try {
 const { readFileSync } = await import("node:fs");
 const { basename } = await import("node:path");
 formData = new FormData();
 formData.append("file", new Blob([readFileSync(filePath)]), basename(filePath));
 }
 catch {
 spinner.fail("Failed to read file");
 error(`Could not read file: ${filePath}`);
 return;
 }
 formData.append("login_cookies", .login_cookies);
 formData.append("proxy", .proxy);
 const url = `${resolveBases().domain}/twitter/upload_media_v2`;
 const res = await fetch(url, {
 method: "POST",
 headers: {
 : `Bearer ${key}`,
 "x-aisa-source": "cli",
 },
 body: formData,
 });
 if (!res.ok) {
 spinner.fail("Upload failed");
 const text = await res.text();
 error(`${res.status}: ${text}`);
 return;
 }
 const data = await res.json();
 spinner.stop();
 if (options.raw) {
 console.log(JSON.stringify(data));
 }
 else {
 success("Media uploaded!");
 console.log(formatJson(data));
 }
}
